<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Dune Line — The overnight train to Vesper City</title>
<meta name="description" content="Dune Line is the overnight sleeper across the Sable Desert. Fall asleep in the dunes, wake up in neon.">
<meta name="theme-color" content="#0c0920">
<style>
:root{
  --night-900:#0b0819; --night-800:#100b24; --night-700:#171031; --dune:#140a25;
  --sand-100:#f4e8d2; --sand-200:#ecdcbd; --ink:#1d1230;
  --cream:#f6ecd9; --amber:#ffb65c; --ember:#f2683c; --terra:#b94a27;
  --pink:#ff4fa3; --violet:#8f6bff; --cyan:#4ff0e0;
  --serif:"Iowan Old Style","Palatino Linotype",Palatino,"Book Antiqua","URW Palladio L",P052,Georgia,serif;
  --sans:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
  --mono:ui-monospace,"SF Mono","Cascadia Mono","Segoe UI Mono",Menlo,Consolas,"Liberation Mono",monospace;
}
*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth;scroll-padding-top:92px;-webkit-text-size-adjust:100%}
body{margin:0;font-family:var(--sans);font-size:17px;line-height:1.6;color:var(--cream);background:var(--night-900);-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
h1,h2,h3,p,figure,blockquote{margin:0}
a{color:inherit}
svg{display:block}
:focus-visible{outline:2px solid var(--cyan);outline-offset:3px;border-radius:6px}
.wrap{width:100%;max-width:1280px;margin:0 auto;padding:0 clamp(20px,4vw,40px)}
.skip{position:absolute;left:16px;top:-60px;background:var(--amber);color:var(--ink);padding:10px 16px;border-radius:10px;z-index:100;font-weight:600;text-decoration:none}
.skip:focus{top:12px}

/* ---------- shared type ---------- */
.eyebrow{display:inline-flex;align-items:center;gap:12px;font:500 12.5px/1.4 var(--mono);letter-spacing:.16em;text-transform:uppercase;color:var(--e,var(--amber))}
.eyebrow::before{content:"";width:28px;height:1px;background:currentColor}
h2{font-family:var(--serif);font-weight:400;font-size:clamp(32px,4vw,52px);line-height:1.08;letter-spacing:-.015em;text-wrap:balance}
h2 em{font-style:italic}
.sec-head{display:grid;grid-template-columns:1.25fr .75fr;gap:48px;align-items:end;margin-bottom:clamp(40px,5vw,68px)}
.sec-head h2{margin-top:18px}
.sec-head p{font-size:17.5px;max-width:42ch}

/* ---------- buttons ---------- */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;height:52px;padding:0 26px;border-radius:999px;font:600 15.5px/1 var(--sans);letter-spacing:.01em;text-decoration:none;border:1px solid transparent;cursor:pointer;white-space:nowrap;transition:transform .2s ease,box-shadow .2s ease,background-color .2s ease,border-color .2s ease}
.btn--primary{background:var(--amber);color:var(--ink);box-shadow:0 12px 30px -12px rgba(255,182,92,.75)}
.btn--primary:hover{background:#ffc67e;transform:translateY(-2px)}
.btn--ghost{border-color:rgba(246,236,217,.28);color:var(--cream)}
.btn--ghost:hover{border-color:rgba(246,236,217,.65);background:rgba(246,236,217,.06)}
.btn--neon{background:linear-gradient(100deg,#ff4fa3,#a35cff);color:#fff;box-shadow:0 14px 36px -12px rgba(255,79,163,.8)}
.btn--neon:hover{transform:translateY(-2px);box-shadow:0 18px 44px -12px rgba(255,79,163,.95)}
.btn--sm{height:42px;padding:0 20px;font-size:14.5px}
.btn svg{transition:transform .2s ease}
.btn:hover svg{transform:translateX(3px)}

/* ---------- nav ---------- */
.nav{position:fixed;inset:0 0 auto 0;z-index:50;border-bottom:1px solid transparent;transition:background-color .3s ease,border-color .3s ease}
.nav.is-stuck,.nav.is-open{background:rgba(11,8,25,.82);-webkit-backdrop-filter:blur(14px) saturate(140%);backdrop-filter:blur(14px) saturate(140%);border-color:rgba(255,255,255,.08)}
.nav__in{display:flex;align-items:center;justify-content:space-between;height:76px;gap:24px}
.brand{display:inline-flex;align-items:center;gap:12px;text-decoration:none;color:var(--cream);font-family:var(--serif);font-size:23px;letter-spacing:.005em}
.nav__links{display:flex;gap:38px;list-style:none;margin:0;padding:0}
.nav__links a{position:relative;text-decoration:none;font-size:15px;color:rgba(246,236,217,.76);padding:8px 0;transition:color .2s}
.nav__links a::after{content:"";position:absolute;left:0;right:0;bottom:2px;height:1px;background:var(--amber);transform:scaleX(0);transform-origin:left;transition:transform .25s ease}
.nav__links a:hover{color:var(--cream)}
.nav__links a:hover::after{transform:scaleX(1)}
.nav__right{display:flex;align-items:center;gap:12px}
.nav__toggle{display:none;width:42px;height:42px;border-radius:50%;border:1px solid rgba(246,236,217,.28);background:none;color:var(--cream);cursor:pointer;padding:0;align-items:center;justify-content:center}
.nav__toggle span,.nav__toggle span::before{display:block;width:16px;height:1.5px;background:currentColor;position:relative;transition:transform .2s}
.nav__toggle span::before{content:"";position:absolute;top:6px}
.nav__toggle span{transform:translateY(-3px)}
.nav.is-open .nav__toggle span{transform:rotate(45deg)}
.nav.is-open .nav__toggle span::before{transform:translateY(-6px) rotate(-90deg)}

/* ---------- hero ---------- */
.hero{position:relative;overflow:hidden;min-height:780px;min-height:clamp(780px,100vh,960px);min-height:clamp(780px,100svh,960px);
  background:radial-gradient(90% 70% at 88% 0%,#080920 0%,rgba(8,9,32,0) 65%),linear-gradient(180deg,#0c0920 0%,#1a0f3c 42%,#3a1757 74%,#55205f 100%)}
.stars{position:absolute;inset:0;z-index:0;pointer-events:none}
.stars i{position:absolute;border-radius:50%;background:#fff;opacity:var(--o,.6);animation:twinkle 4s ease-in-out infinite}
@keyframes twinkle{50%{opacity:calc(var(--o,.6)*.3)}}
.moon{position:absolute;z-index:0;top:128px;right:12%;width:54px;height:54px;filter:drop-shadow(0 0 18px rgba(246,236,217,.45))}
.scene{position:absolute;left:0;bottom:0;z-index:1;width:100%;height:clamp(300px,43.75vw,640px);overflow:visible;pointer-events:none}
.hero__in{position:relative;z-index:3;padding-top:148px}
.hero h1{font-family:var(--serif);font-weight:400;font-size:clamp(42px,6.4vw,88px);line-height:1.03;letter-spacing:-.022em;margin-top:26px}
.hero h1 em{font-style:italic;color:#ffe0ef;text-shadow:0 0 14px rgba(255,79,163,.9),0 0 44px rgba(255,79,163,.55),0 0 90px rgba(143,107,255,.5)}
.hero__lede{margin-top:26px;max-width:560px;font-size:clamp(17px,1.5vw,19px);line-height:1.6;color:rgba(246,236,217,.8)}
.hero__cta{display:flex;flex-wrap:wrap;gap:12px;margin-top:34px}
.train{animation:arrive 2.6s cubic-bezier(.16,.7,.2,1) both}
@keyframes arrive{from{transform:translateX(-240px)}to{transform:none}}
.beacon{animation:blink 2.4s steps(1,end) infinite}
@keyframes blink{0%,60%{opacity:1}61%,100%{opacity:.15}}
.halo{animation:hum 5s ease-in-out infinite}
@keyframes hum{50%{opacity:.72}}

/* ---------- route band ---------- */
.route{position:relative;z-index:2;background:var(--dune);margin-top:-1px;padding:40px 0 150px}
.route__head{display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px 24px;font:500 12px/1.5 var(--mono);letter-spacing:.14em;text-transform:uppercase;color:rgba(246,236,217,.5);margin-bottom:36px}
.route__head b{font-weight:500;color:var(--cream)}
.stops{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,1fr);position:relative}
.stops::before{content:"";position:absolute;left:7px;right:calc(25% - 7px);top:6px;height:2px;border-radius:2px;background:linear-gradient(90deg,var(--amber),var(--ember) 34%,var(--pink) 68%,var(--cyan))}
.stops li{position:relative;padding:36px 28px 0 0}
.stops li::before{content:"";position:absolute;left:0;top:0;width:14px;height:14px;border-radius:50%;background:var(--dune);border:2px solid var(--c);box-shadow:0 0 0 5px var(--dune),0 0 22px 4px var(--c)}
.stops time{display:block;font:500 13px/1 var(--mono);letter-spacing:.08em;color:var(--c)}
.stops strong{display:block;font:400 25px/1.2 var(--serif);margin-top:10px}
.stops span{display:block;font-size:14.5px;color:rgba(246,236,217,.6);margin-top:4px}
.route__dune{position:absolute;left:0;right:0;bottom:-1px;width:100%;height:clamp(40px,6vw,84px)}

/* ---------- features ---------- */
.features{background:linear-gradient(180deg,var(--sand-100),var(--sand-200));color:var(--ink);padding:clamp(56px,7vw,96px) 0 clamp(80px,10vw,136px)}
.features .eyebrow,.quote .eyebrow{--e:var(--terra)}
.features h2 em,.quote em{color:var(--terra)}
.features .sec-head p{color:rgba(29,18,48,.72)}
.features__grid{display:grid;grid-template-columns:repeat(3,1fr);gap:clamp(24px,3.2vw,44px)}
.pane{background:var(--ink);padding:10px;border-radius:36px;box-shadow:0 34px 50px -32px rgba(29,18,48,.7)}
.pane__glass{border-radius:27px;overflow:hidden}
.pane svg{width:100%;height:auto}
.feature__k{display:flex;align-items:center;gap:10px;margin-top:30px;font:500 12px/1 var(--mono);letter-spacing:.15em;text-transform:uppercase;color:var(--terra)}
.feature__k i{flex:0 0 18px;height:1px;background:currentColor}
.feature h3{font:400 29px/1.15 var(--serif);letter-spacing:-.01em;margin:14px 0 12px}
.feature p{font-size:16.5px;color:rgba(29,18,48,.74)}
.feature__meta{margin-top:20px;padding-top:16px;border-top:1px solid rgba(29,18,48,.16);font:500 12px/1.5 var(--mono);letter-spacing:.08em;text-transform:uppercase;color:rgba(29,18,48,.62)}

/* ---------- timetable ---------- */
.times{background:linear-gradient(180deg,#0d0a1f,var(--night-900));padding:clamp(80px,10vw,136px) 0}
.times .sec-head p{color:rgba(246,236,217,.68)}
.clockbox{justify-self:end;text-align:right}
.clock{display:inline-flex;align-items:center;gap:14px;padding:10px 16px 10px 14px;border:1px solid rgba(255,255,255,.12);border-radius:999px;font:500 12px/1 var(--mono);letter-spacing:.14em;text-transform:uppercase;color:rgba(246,236,217,.6)}
.clock i{width:8px;height:8px;border-radius:50%;background:var(--amber);box-shadow:0 0 12px var(--amber)}
.clock time{font-size:15px;letter-spacing:.06em;color:var(--amber);font-variant-numeric:tabular-nums}
.next{margin-top:14px;font-size:15px;color:rgba(246,236,217,.68)}
.next strong{color:var(--cream);font-weight:600}
.board-wrap{border:1px solid rgba(255,255,255,.09);border-radius:24px;background:linear-gradient(180deg,#181133,#110b27);overflow:hidden;box-shadow:0 50px 100px -60px #000}
.board{width:100%;border-collapse:collapse;text-align:left}
.board thead th{font:500 11.5px/1 var(--mono);letter-spacing:.14em;text-transform:uppercase;color:rgba(246,236,217,.55);padding:22px 18px;border-bottom:1px solid rgba(255,255,255,.09);vertical-align:top}
.board thead small{display:block;margin-top:7px;font-size:10.5px;letter-spacing:.1em;color:rgba(246,236,217,.5)}
.board tbody th,.board tbody td{padding:25px 18px;border-bottom:1px solid rgba(255,255,255,.06);vertical-align:middle;font-weight:400;transition:background-color .2s}
.board tbody tr:last-child>*{border-bottom:0}
.board tr>:first-child{padding-left:32px}
.board tr>:last-child{padding-right:32px}
.board tbody tr:hover>*{background:rgba(255,255,255,.025)}
.board tbody tr.is-next>*{background:rgba(255,182,92,.065)}
.board tbody tr.is-next>th{box-shadow:inset 3px 0 0 var(--amber)}
.svc{display:flex;align-items:center;gap:16px}
.svc__no{flex:none;font:500 12px/1 var(--mono);letter-spacing:.08em;padding:8px 9px;border:1px solid rgba(246,236,217,.24);border-radius:8px;color:rgba(246,236,217,.82)}
.svc__name{font:400 23px/1.2 var(--serif)}
.svc__tag{display:none;margin-left:10px;vertical-align:3px;font:600 10.5px/1 var(--mono);letter-spacing:.12em;text-transform:uppercase;color:var(--ink);background:var(--amber);padding:5px 8px;border-radius:999px}
.is-next .svc__tag{display:inline-block}
.t{font:500 30px/1 var(--mono);letter-spacing:-.02em;font-variant-numeric:tabular-nums;white-space:nowrap}
.t--dep{color:var(--amber)}
.t--arr{color:#8ff7ec;text-shadow:0 0 22px rgba(79,240,224,.45)}
.t sup{font-size:11px;letter-spacing:.04em;color:rgba(246,236,217,.6);margin-left:5px;vertical-align:top;position:relative;top:2px;text-shadow:none}
.dur{font:500 14px/1.4 var(--mono);color:rgba(246,236,217,.85);white-space:nowrap}
.dur small{display:block;font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:rgba(246,236,217,.55);margin-top:3px}
.calls{font-size:14.5px;color:rgba(246,236,217,.7)}
.pill{display:inline-flex;align-items:center;gap:8px;padding:7px 12px 7px 10px;border-radius:999px;font-size:13px;font-weight:500;white-space:nowrap;border:1px solid var(--p);color:var(--p)}
.pill::before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor}
.pill--ok{--p:#7fe9c9}.pill--warn{--p:#ffb65c}.pill--muted{--p:rgba(246,236,217,.6)}
.board-note{display:flex;flex-wrap:wrap;gap:8px 32px;margin-top:22px;font-size:14px;color:rgba(246,236,217,.6)}
.board-note span::before{content:"";display:inline-block;width:4px;height:4px;border-radius:50%;background:var(--amber);margin-right:10px;vertical-align:middle}

/* ---------- testimonial ---------- */
.quote{background:linear-gradient(180deg,var(--sand-100),#f3dcbd);color:var(--ink);padding:clamp(80px,10vw,136px) 0}
.quote__in{display:grid;grid-template-columns:220px 1fr;gap:64px}
.quote__mark{font:400 190px/1 var(--serif);color:var(--terra);height:112px;margin-top:22px;user-select:none}
.quote blockquote p{font:400 clamp(25px,3.1vw,40px)/1.26 var(--serif);letter-spacing:-.012em;text-wrap:pretty}
.quote figcaption{display:flex;align-items:center;gap:16px;margin-top:44px;padding-top:28px;border-top:1px solid rgba(29,18,48,.16)}
.avatar{flex:none;width:52px;height:52px;border-radius:50%;display:grid;place-items:center;font:400 19px/1 var(--serif);color:var(--ink);background:linear-gradient(135deg,var(--amber),#ff8f7a 60%,#ff6fae)}
.quote__who strong{display:block;font-weight:600;font-size:16.5px}
.quote__who span{font-size:15px;color:rgba(29,18,48,.7)}
.quote__trip{margin-left:auto;font:500 12px/1.5 var(--mono);letter-spacing:.12em;text-transform:uppercase;color:rgba(29,18,48,.65);text-align:right}

/* ---------- fares ---------- */
.fares{position:relative;overflow:hidden;background:var(--night-900);padding:clamp(80px,10vw,136px) 0}
.fares::before{content:"";position:absolute;inset:0;pointer-events:none;background:radial-gradient(620px 420px at 10% 8%,rgba(255,79,163,.17),transparent 70%),radial-gradient(720px 480px at 92% 88%,rgba(79,240,224,.11),transparent 70%),radial-gradient(520px 380px at 50% 60%,rgba(143,107,255,.12),transparent 70%)}
.fares .wrap{position:relative}
.fares .eyebrow{--e:#ff86c0}
.fares__head{text-align:center;max-width:720px;margin:0 auto clamp(44px,5vw,64px)}
.fares__head h2{margin-top:18px}
.fares__head p{margin-top:18px;color:rgba(246,236,217,.7)}
.seg{display:inline-flex;margin-top:30px;padding:5px;border-radius:999px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1)}
.seg button{appearance:none;border:0;background:none;color:rgba(246,236,217,.75);font:600 14.5px/1 var(--sans);height:40px;padding:0 20px;border-radius:999px;cursor:pointer;display:inline-flex;align-items:center;gap:8px;transition:background-color .2s,color .2s}
.seg button[aria-pressed="true"]{background:var(--cream);color:var(--ink)}
.seg button span{font:600 11px/1 var(--mono);padding:4px 6px;border-radius:999px;background:rgba(255,79,163,.2);color:#ff9acb}
.seg button[aria-pressed="true"] span{background:var(--ink);color:#ff9acb}
.tiers{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;align-items:stretch}
.tier{position:relative;display:flex;flex-direction:column;padding:36px 32px 34px;border-radius:26px;border:1px solid rgba(255,255,255,.1);background:linear-gradient(180deg,rgba(255,255,255,.055),rgba(255,255,255,.018))}
.tier--featured{border:1.5px solid transparent;background:linear-gradient(180deg,#23153f,#160d2d) padding-box,linear-gradient(140deg,#ff4fa3,#8f6bff 52%,#4ff0e0) border-box;box-shadow:0 40px 90px -40px rgba(255,79,163,.6);transform:translateY(-14px)}
.tier__badge{position:absolute;top:22px;right:22px;font:600 10.5px/1 var(--mono);letter-spacing:.12em;text-transform:uppercase;color:#ffd3ea;padding:7px 10px;border-radius:999px;background:rgba(255,79,163,.16);border:1px solid rgba(255,79,163,.5)}
.tier__kind{display:flex;align-items:center;gap:10px;font:500 12px/1 var(--mono);letter-spacing:.14em;text-transform:uppercase;color:var(--a)}
.tier__kind::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--a);box-shadow:0 0 14px var(--a)}
.tier h3{font:400 38px/1.1 var(--serif);letter-spacing:-.01em;margin-top:18px}
.tier__desc{margin-top:10px;font-size:15.5px;color:rgba(246,236,217,.68);min-height:3.2em}
.tier__price{display:flex;align-items:flex-start;gap:4px;margin-top:26px;font-family:var(--serif)}
.tier__cur{font-size:24px;line-height:1;margin-top:9px;color:rgba(246,236,217,.75)}
.tier__amt{font-size:68px;line-height:1;letter-spacing:-.03em;font-variant-numeric:lining-nums}
.tier__per{align-self:flex-end;margin:0 0 9px 8px;font:400 14px/1.35 var(--sans);color:rgba(246,236,217,.62)}
.tier .btn{margin-top:28px;width:100%}
.tier ul{list-style:none;margin:28px 0 0;padding:24px 0 0;border-top:1px solid rgba(255,255,255,.1)}
.tier li{position:relative;padding-left:30px;margin:0 0 13px;font-size:15.5px;line-height:1.45;color:rgba(246,236,217,.84)}
.tier li:last-child{margin-bottom:0}
.tier li::before{content:"";position:absolute;left:5px;top:.22em;width:6px;height:11px;border:solid var(--a);border-width:0 2px 2px 0;transform:rotate(42deg)}
.fares__note{margin-top:40px;text-align:center;font-size:14px;color:rgba(246,236,217,.6)}

/* ---------- footer ---------- */
.foot{background:#08060f;padding:clamp(72px,9vw,120px) 0 36px}
.foot__cta{display:flex;align-items:flex-end;justify-content:space-between;flex-wrap:wrap;gap:32px}
.foot__cta h2{max-width:14em}
.foot__cta h2 em{color:#ffe0ef;text-shadow:0 0 14px rgba(255,79,163,.85),0 0 44px rgba(255,79,163,.5)}
.foot__btns{display:flex;flex-wrap:wrap;gap:12px}
.foot__line{height:2px;margin:clamp(48px,6vw,80px) 0;border-radius:2px;background:linear-gradient(90deg,var(--amber),var(--ember) 30%,var(--pink) 64%,var(--cyan));box-shadow:0 0 24px rgba(255,79,163,.55)}
.foot__grid{display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr;gap:40px}
.foot__about p{margin-top:18px;max-width:30ch;font-size:15px;color:rgba(246,236,217,.62)}
.foot h3{font:500 12px/1 var(--mono);letter-spacing:.14em;text-transform:uppercase;color:rgba(246,236,217,.6);margin:8px 0 18px}
.foot ul{list-style:none;margin:0;padding:0}
.foot li{margin-bottom:10px}
.foot li a{text-decoration:none;font-size:15.5px;color:rgba(246,236,217,.82);transition:color .2s}
.foot li a:hover{color:var(--amber)}
.foot__base{display:flex;justify-content:space-between;flex-wrap:wrap;gap:10px 24px;margin-top:64px;padding-top:24px;border-top:1px solid rgba(255,255,255,.08);font-size:13.5px;color:rgba(246,236,217,.6)}

/* ---------- responsive ---------- */
@media (max-width:1040px){
  .tiers{grid-template-columns:1fr;max-width:540px;margin:0 auto}
  .tier--featured{transform:none}
  .tier__desc{min-height:0}
}
@media (max-width:960px){
  .sec-head{grid-template-columns:1fr;gap:20px;align-items:start}
  .clockbox{justify-self:start;text-align:left}
  .features__grid{grid-template-columns:1fr;gap:48px}
  .feature{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1fr);gap:32px;align-items:center}
  .feature__k{margin-top:0}
  .quote__in{grid-template-columns:1fr;gap:8px}
  .quote__mark{margin-top:10px}
  .foot__grid{grid-template-columns:1fr 1fr 1fr}
  .foot__about{grid-column:1/-1}
}
@media (max-width:880px){
  .nav__toggle{display:inline-flex}
  .nav__links{display:none;position:absolute;left:0;right:0;top:76px;flex-direction:column;gap:0;padding:8px clamp(20px,4vw,40px) 20px;background:rgba(11,8,25,.96);border-bottom:1px solid rgba(255,255,255,.08)}
  .nav.is-open .nav__links{display:flex}
  .nav__links a{display:block;padding:14px 0;font-size:17px;border-bottom:1px solid rgba(255,255,255,.07)}
  .nav__links a::after{display:none}
  .board thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
  .board,.board tbody{display:block}
  .board tbody tr{display:grid;grid-template-columns:1fr 1fr;gap:18px 16px;padding:24px 22px;border-bottom:1px solid rgba(255,255,255,.07)}
  .board tbody tr:last-child{border-bottom:0}
  .board tbody th,.board tbody td{display:block;padding:0!important;border:0;background:none!important;box-shadow:none!important}
  .board tbody th{grid-column:1/-1}
  .board tbody tr.is-next{background:rgba(255,182,92,.065);box-shadow:inset 3px 0 0 var(--amber)}
  .board td::before{content:attr(data-label);display:block;font:500 10.5px/1 var(--mono);letter-spacing:.14em;text-transform:uppercase;color:rgba(246,236,217,.55);margin-bottom:8px}
}
@media (max-width:720px){
  .hero{min-height:0;padding-bottom:300px}
  .hero__in{padding-top:124px}
  .hero h1 br{display:none}
  .moon{top:92px;right:8%;width:40px;height:40px}
  .route{padding-bottom:110px}
  .stops{grid-template-columns:1fr;gap:28px}
  .stops::before{left:6px;right:auto;top:8px;bottom:40px;width:2px;height:auto;background:linear-gradient(180deg,var(--amber),var(--ember) 34%,var(--pink) 68%,var(--cyan))}
  .stops li{padding:0 0 0 38px}
  .stops li::before{top:0}
  .feature{display:block}
  .feature__k{margin-top:26px}
  .quote figcaption{flex-wrap:wrap}
  .quote__trip{margin-left:68px;text-align:left;width:100%}
  .foot__grid{grid-template-columns:1fr 1fr}
}
@media (max-width:560px){
  .scene{transform:translateX(-70px)}
  .nav .btn{display:none}
  .btn{height:50px}
  .hero__cta .btn{flex:1 1 100%}
  .t{font-size:26px}
  .tier{padding:30px 24px}
}
@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  *,*::before,*::after{animation:none!important;transition:none!important}
}
</style>
