<script>
(function(){
  var d=document;

  /* nav: solid on scroll + mobile menu */
  var nav=d.querySelector('.nav'), tg=d.querySelector('.nav__toggle'), menu=d.getElementById('menu');
  function onScroll(){nav.classList.toggle('is-stuck',window.scrollY>24)}
  onScroll(); window.addEventListener('scroll',onScroll,{passive:true});
  tg.addEventListener('click',function(){
    var open=nav.classList.toggle('is-open'); tg.setAttribute('aria-expanded',String(open));
  });
  menu.addEventListener('click',function(e){
    if(e.target.closest('a')){nav.classList.remove('is-open');tg.setAttribute('aria-expanded','false')}
  });

  /* stars: seeded so the sky is the same every visit */
  var sky=d.querySelector('.stars');
  if(sky){
    var seed=11;
    var rnd=function(){seed|=0;seed=seed+0x6D2B79F5|0;var t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296};
    var frag=d.createDocumentFragment();
    for(var i=0;i<120;i++){
      var x=rnd()*100, y=Math.pow(rnd(),1.3)*66, k=rnd();
      var size=k<.1?2.4:(k<.5?1.6:1);
      var o=Math.max(.12,(.35+rnd()*.65)*(1-y/80));
      var s=d.createElement('i');
      s.style.cssText='left:'+x.toFixed(2)+'%;top:'+y.toFixed(2)+'%;width:'+size+'px;height:'+size+'px;--o:'+o.toFixed(2)+';animation-delay:-'+(rnd()*6).toFixed(2)+'s;animation-duration:'+(3+rnd()*4).toFixed(2)+'s';
      frag.appendChild(s);
    }
    sky.appendChild(frag);
  }

  /* timetable: live clock + next departure */
  var rows=[].slice.call(d.querySelectorAll('.board tbody tr')), clock=d.getElementById('clock'), note=d.getElementById('next-note');
  function mins(t){var p=t.split(':');return (+p[0])*60+(+p[1])}
  function pad(n){return (n<10?'0':'')+n}
  function tick(){
    var n=new Date(), m=n.getHours()*60+n.getMinutes(), next=null, wait=0;
    if(clock) clock.textContent=pad(n.getHours())+':'+pad(n.getMinutes())+':'+pad(n.getSeconds());
    rows.forEach(function(r){var dm=mins(r.getAttribute('data-dep')); if(!next&&dm>m){next=r;wait=dm-m}});
    if(!next&&rows.length){next=rows[0];wait=mins(rows[0].getAttribute('data-dep'))+1440-m}
    rows.forEach(function(r){r.classList.toggle('is-next',r===next)});
    if(note&&next){
      var h=Math.floor(wait/60), mm=wait%60;
      note.innerHTML='Next out: <strong>'+next.getAttribute('data-name')+'</strong> in '+(h?h+' h ':'')+mm+' min';
    }
  }
  if(rows.length){tick();setInterval(tick,1000)}

  /* fares: one way / return */
  var seg=[].slice.call(d.querySelectorAll('.seg button'));
  seg.forEach(function(b){
    b.addEventListener('click',function(){
      var mode=b.getAttribute('data-mode');
      seg.forEach(function(x){x.setAttribute('aria-pressed',String(x===b))});
      [].forEach.call(d.querySelectorAll('.tier__amt'),function(el){el.textContent=el.getAttribute('data-'+mode)});
      [].forEach.call(d.querySelectorAll('[data-per]'),function(el){el.textContent=mode==='return'?'return':'one way'});
    });
  });
})();
</script>
